from pathlib import Path
D=Path(__file__).resolve().parent;p=D/'p5-frontend-regression-browser.mjs';assert not p.exists(),'Refuse overwrite test'
t=(D/'p5-regression-browser-test.mjs').read_text(encoding='utf-8').replace('docs/p5-evidence/browser-','docs/p5-frontend-evidence/flow-').replace('originalReactChanged:false','approvedFrontendChangesOnly:true').replace('scannerUiAvailable:false','scannerUiAvailable:true').replace('ruleValidatorUiAvailable:false','ruleValidatorUiAvailable:true').replace("simulationSurface:'real Edge executing original API client; not a scanner button UI'","simulationSurface:'actual scan simulator and validator form clicks'")
marker='try{\n browser=await chromium.launch'
helpers='''async function pageScan(p,value){await p.goto('http://127.0.0.1:15173/scan-simulator');await p.getByRole('heading',{name:'扫码模拟',exact:true}).waitFor();await p.getByLabel('模拟凭证值').fill(value);const pending=p.waitForResponse(r=>new URL(r.url()).pathname==='/api/access-records/simulate'&&r.request().method()==='POST');await p.getByRole('button',{name:'执行核验',exact:true}).click();const r=await pending;return{ok:r.status()===200,data:(await r.json()).data};}
async function pageValidate(p,value){await p.locator('label').filter({hasText:/^验证凭证类型/}).locator('select').selectOption('qr');await p.getByLabel('验证凭证值').fill(value);const pending=p.waitForResponse(r=>new URL(r.url()).pathname==='/api/access-rules/validate'&&r.request().method()==='POST');await p.getByRole('button',{name:'验证通行规则',exact:true}).click();const r=await pending;return{ok:r.status()===200,data:(await r.json()).data};}
'''
assert marker in t;t=t.replace(marker,helpers+marker)
t=t.replace("await client(guard,'simulateScan',[{credentialType:'qr',credentialValue:decoded.data,gate:'东门'}])","await pageScan(guard,decoded.data)").replace("await client(guard,'simulateScan',[{credentialType:'qr',credentialValue:'SYN-INVALID-QR',gate:'东门'}])","await pageScan(guard,'SYN-INVALID-QR')").replace("await client(admin,'validateAccessRule',[{credentialType:'qr',credentialValue:decoded.data,gate:'东门'}])","await pageValidate(admin,decoded.data)")
t=t.replace("'browser-original-client-real-qr-simulation'","'actual-scan-page-issued-qr'").replace("'browser-original-client-rule-validation'","'actual-validator-page-issued-qr'").replace("surface:'original API client in real Edge; no active scanner UI'","surface:'actual scan form submit'").replace("surface:'original API client; validator JSX absent'","surface:'actual validator form submit'").replace('scannerUiNotClaimed:true','scannerUiVerified:true')
anchor="await screenshot(admin,'blacklist-removed');"
extra="""const reportLoaded=admin.waitForResponse(r=>new URL(r.url()).pathname==='/api/reports/summary'&&r.status()===200);await admin.goto('http://127.0.0.1:15173/reports');const summary=(await(await reportLoaded).json()).data;await admin.getByRole('heading',{name:/统计|报表/}).first().waitFor();const reportsDb=await connect();try{check('statistics-original-page-real-sql',summary.access.total===Number((await reportsDb.query('SELECT COUNT(*) n FROM access_records'))[0][0].n));}finally{await reportsDb.end();}await screenshot(admin,'reports-current');"""
assert anchor in t;t=t.replace(anchor,anchor+extra);p.write_text(t,encoding='utf-8');print('Prepared real form-click core flow regression without changing historical scripts')
